namespace DmiCad;

static class Brand
{
    // Original DMI로고.png from the user's Drive. Preserve aspect ratio and colors.
    public const string LogoBase64 = "";
    public const string Meaning = "Design · Mold · Injection";
    public static string HtmlLogo => "<img alt='DMI — Design, Mold, Injection' style='width:110px;height:auto;display:block;margin-bottom:14px' src='data:image/png;base64," + LogoBase64 + "'>";
    public static Image CreateLogo()
    {
        using var stream = new MemoryStream(Convert.FromBase64String(LogoBase64));
        using var original = Image.FromStream(stream);
        return new Bitmap(original);
    }
}
